-- AlterTable: add finance columns to tasks table if they don't exist yet (idempotent for raw SQL migration path used in project)  -- NOTE: this migration is applied via `npx prisma migrate dev` or `prisma db push` on the server  -- Add finance columns to Task table  ALTER TABLE tasks ADD COLUMN IF NOT EXISTS budget DOUBLE PRECISION DEFAULT 0;  ALTER TABLE tasks ADD COLUMN IF NOT EXISTS price DOUBLE PRECISION DEFAULT 0;    -- Create TaskTransaction table  CREATE TABLE IF NOT EXISTS task_transactions (    id TEXT PRIMARY KEY DEFAULT gen_random_uuid(),    task_id TEXT NOT NULL,    type TEXT NOT NULL,    amount DOUBLE PRECISION NOT NULL,    description TEXT,    date TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP  );    CREATE INDEX IF NOT EXISTS task_transactions_task_id_date_idx ON task_transactions(task_id, date);    ALTER TABLE task_transactions    ADD CONSTRAINT task_transactions_task_id_fkey    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE ON UPDATE CASCADE;